<script setup lang="ts">
type Event={id:string;event:string;status:string;analysisId:string|null;analysisTitle:string|null;contentId:string|null;contentTitle:string|null;predictionId:string|null;details:any;createdAt:string};const config=useRuntimeConfig();const api=String(config.public.apiBase||"");const events=ref<Event[]>([]);const loading=ref(true);const error=ref("");async function load(){loading.value=true;error.value="";try{const r=await $fetch<{events:Event[];message?:string}>(`${api}/api/activity`,{credentials:"include"});events.value=r.events||[]}catch(e:any){error.value=e?.data?.message||"Unable to load activity history."}finally{loading.value=false}}await load();const labels:Record<string,string>={INVESTIGATION_CREATED:"Investigation created",EVIDENCE_ADDED:"Evidence added",EVIDENCE_REMOVED:"Evidence removed",PREDICTION_EXECUTED:"Prediction executed",INVESTIGATION_STATUS_CHANGED:"Investigation status changed"};
</script>
<template><main class="mx-auto max-w-5xl space-y-6 p-5 sm:p-8"><div class="mb-4"><DashboardBackToDashboard /></div><DashboardNav/><header><p class="text-xs font-semibold uppercase tracking-widest text-[var(--vl-sage-dark)]">System</p><h1 class="mt-2 text-3xl font-semibold">Activity history</h1><p class="mt-2 text-sm text-[var(--vl-muted)]">Recorded investigation, evidence, and prediction events.</p></header><div v-if="loading" class="rounded-2xl bg-white/70 p-7">Loading activity…</div><div v-else-if="error" class="rounded-2xl border border-red-200 p-6">{{error}} <button class="ml-2 underline" @click="load">Retry</button></div><div v-else-if="!events.length" class="rounded-2xl border border-dashed p-10 text-center text-[var(--vl-muted)]">No activity has been recorded yet.</div><div v-else class="space-y-3"><article v-for="e in events" :key="e.id" class="rounded-2xl border border-[var(--vl-border)] bg-white/70 p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold">{{labels[e.event]||e.event}}</p><NuxtLink v-if="e.analysisId" :to="`/dashboard/analyses/${e.analysisId}`" class="mt-1 block text-sm underline">{{e.analysisTitle||'Investigation'}}</NuxtLink><p v-if="e.contentTitle" class="mt-1 text-sm text-[var(--vl-muted)]">{{e.contentTitle}}<span v-if="e.details?.type"> · {{e.details.type}}</span></p><p v-if="e.details?.prediction" class="mt-1 text-sm text-[var(--vl-muted)]">{{e.details.prediction}} · {{Math.round(e.details.confidence*100)}}% confidence</p></div><div class="text-right"><span class="rounded-full bg-[#e8ece2] px-3 py-1 text-xs">{{e.status}}</span><time class="mt-2 block text-xs text-[var(--vl-muted)]">{{new Date(e.createdAt).toLocaleString()}}</time></div></div></article></div></main></template>

